'use strict';

// Reproductions for INC-5521. Every test here drives the service with
// concurrent calls against the latency-modelling store, the way the checkout
// fleet does, and checks the counters afterwards.

const test = require('node:test');
const assert = require('node:assert/strict');
const {
  InventoryService,
  Store,
  InsufficientStockError,
  UnknownSkuError,
  OrderStateError
} = require('../src');

async function service(stock, options = {}) {
  const svc = new InventoryService(options);
  for (const [sku, qty] of Object.entries(stock)) {
    await svc.addStock(sku, qty);
  }
  return svc;
}

function settle(promises) {
  return Promise.allSettled(promises).then(results => ({
    fulfilled: results.filter(r => r.status === 'fulfilled').map(r => r.value),
    rejected: results.filter(r => r.status === 'rejected').map(r => r.reason)
  }));
}

// Fails the test instead of hanging when a call is stuck behind a lock it
// should not be waiting for.
function within(ms, promise) {
  let timer;
  const timeout = new Promise((_, reject) => {
    timer = setTimeout(() => reject(new Error(`still waiting after ${ms}ms`)), ms);
  });
  return Promise.race([promise, timeout]).finally(() => clearTimeout(timer));
}

// A store whose reads and writes of chosen keys can be paused, to show which
// calls wait for which.
class GatedStore extends Store {
  constructor() {
    super();
    this.gates = new Map();
  }

  pause(key) {
    let open;
    this.gates.set(key, new Promise(resolve => { open = resolve; }));
    return () => {
      this.gates.delete(key);
      open();
    };
  }

  async get(key) {
    await this.gates.get(key);
    return super.get(key);
  }

  async set(key, value) {
    await this.gates.get(key);
    return super.set(key, value);
  }
}

// A store with random per-call latency, so interleavings vary between calls.
class JitterStore extends Store {
  constructor(random) {
    super();
    this.random = random;
  }

  async get(key) {
    await this.jitter();
    return super.get(key);
  }

  async set(key, value) {
    await this.jitter();
    return super.set(key, value);
  }

  async keys(prefix) {
    await this.jitter();
    return super.keys(prefix);
  }

  async jitter() {
    for (let i = Math.floor(this.random() * 4); i > 0; i--) {
      await new Promise(resolve => setImmediate(resolve));
    }
  }
}

function prng(seed) {
  return () => {
    seed = (seed * 1103515245 + 12345) & 0x7fffffff;
    return seed / 0x7fffffff;
  };
}

// --- oversold stock -------------------------------------------------------

test('concurrent reserves never hold more than the stock on hand', async () => {
  const svc = await service({ 'sneaker-limited': 250 });
  const orders = Array.from({ length: 300 }, (_, i) => `order-${i}`);

  const { fulfilled, rejected } = await settle(
    orders.map(id => svc.reserve(id, [{ sku: 'sneaker-limited', qty: 1 }]))
  );

  assert.equal(fulfilled.length, 250);
  assert.equal(rejected.length, 50);
  for (const err of rejected) {
    assert.ok(err instanceof InsufficientStockError);
  }
  assert.deepEqual(await svc.snapshot('sneaker-limited'), { sku: 'sneaker-limited', stock: 250, reserved: 250, sold: 0 });

  await Promise.all(fulfilled.map(r => svc.commit(r.orderId)));
  assert.deepEqual(await svc.snapshot('sneaker-limited'), { sku: 'sneaker-limited', stock: 0, reserved: 0, sold: 250 });
});

test('restocking during checkout does not drop held units', async () => {
  const svc = await service({ widget: 10 });

  await Promise.all([
    ...Array.from({ length: 10 }, (_, i) => svc.reserve(`o${i}`, [{ sku: 'widget', qty: 1 }])),
    ...Array.from({ length: 5 }, () => svc.addStock('widget', 2))
  ]);

  assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 20, reserved: 10, sold: 0 });
});

test('concurrent addStock calls all land', async () => {
  const svc = new InventoryService();
  await Promise.all(Array.from({ length: 20 }, () => svc.addStock('widget', 3)));
  assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 60, reserved: 0, sold: 0 });
});

// --- reserved going negative ----------------------------------------------

test('a committed order cannot be released', async () => {
  const svc = await service({ widget: 10 });
  await svc.reserve('o1', [{ sku: 'widget', qty: 3 }]);
  await svc.commit('o1');

  await assert.rejects(svc.release('o1'), err => {
    assert.ok(err instanceof OrderStateError);
    assert.equal(err.status, 'committed');
    return true;
  });
  assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 7, reserved: 0, sold: 3 });
});

test('expire leaves committed and released orders alone', async () => {
  let t = 0;
  const svc = await service({ widget: 10 }, { now: () => t, reservationTtlMs: 1000 });
  await svc.reserve('committed', [{ sku: 'widget', qty: 3 }]);
  await svc.reserve('released', [{ sku: 'widget', qty: 2 }]);
  await svc.reserve('stale', [{ sku: 'widget', qty: 1 }]);
  await svc.commit('committed');
  await svc.release('released');

  t = 5000;
  assert.deepEqual(await svc.expire(), ['stale']);
  assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 7, reserved: 0, sold: 3 });
  assert.equal((await svc.commit('committed')).status, 'committed');
  assert.deepEqual(await svc.expire(), []);
});

test('concurrent releases of one order return its units once', async () => {
  const svc = await service({ widget: 10 });
  await svc.reserve('o1', [{ sku: 'widget', qty: 4 }]);

  const results = await Promise.all(Array.from({ length: 5 }, () => svc.release('o1')));

  for (const r of results) {
    assert.equal(r.status, 'released');
  }
  assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 10, reserved: 0, sold: 0 });
});

test('commit racing release settles on exactly one outcome', async () => {
  for (const first of ['commit', 'release']) {
    const svc = await service({ widget: 10 });
    await svc.reserve('o1', [{ sku: 'widget', qty: 4 }]);

    const calls = first === 'commit'
      ? [svc.commit('o1'), svc.release('o1')]
      : [svc.release('o1'), svc.commit('o1')];
    const { fulfilled, rejected } = await settle(calls);

    assert.equal(fulfilled.length, 1);
    assert.equal(rejected.length, 1);
    assert.ok(rejected[0] instanceof OrderStateError);
    const snap = await svc.snapshot('widget');
    if (fulfilled[0].status === 'committed') {
      assert.deepEqual(snap, { sku: 'widget', stock: 6, reserved: 0, sold: 4 });
    } else {
      assert.deepEqual(snap, { sku: 'widget', stock: 10, reserved: 0, sold: 0 });
    }
  }
});

test('expire racing a commit does not release the committed order', async () => {
  let t = 0;
  const svc = await service({ widget: 10 }, { now: () => t, reservationTtlMs: 1000 });
  await svc.reserve('o1', [{ sku: 'widget', qty: 4 }]);
  t = 5000;

  const [expired, committed] = await Promise.allSettled([svc.expire(), svc.commit('o1')]);

  assert.equal(expired.status, 'fulfilled');
  const snap = await svc.snapshot('widget');
  assert.ok(snap.reserved >= 0);
  if (committed.status === 'fulfilled') {
    assert.deepEqual(expired.value, []);
    assert.deepEqual(snap, { sku: 'widget', stock: 6, reserved: 0, sold: 4 });
    assert.equal((await svc.commit('o1')).status, 'committed');
  } else {
    assert.ok(committed.reason instanceof OrderStateError);
    assert.deepEqual(expired.value, ['o1']);
    assert.deepEqual(snap, { sku: 'widget', stock: 10, reserved: 0, sold: 0 });
  }
});

test('overlapping expire runs release each order once', async () => {
  let t = 0;
  const svc = await service({ widget: 10 }, { now: () => t, reservationTtlMs: 1000 });
  await svc.reserve('o1', [{ sku: 'widget', qty: 4 }]);
  await svc.reserve('o2', [{ sku: 'widget', qty: 2 }]);
  t = 5000;

  const runs = await Promise.all([svc.expire(), svc.expire(), svc.expire()]);

  assert.deepEqual(runs.flat().sort(), ['o1', 'o2']);
  assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 10, reserved: 0, sold: 0 });
});

// --- retried checkout holding stock twice ---------------------------------

test('a retry that overlaps the original request holds stock once', async () => {
  const svc = await service({ widget: 10 });
  const items = [{ sku: 'widget', qty: 3 }];

  const results = await Promise.all(Array.from({ length: 4 }, () => svc.reserve('o1', items)));

  for (const r of results) {
    assert.deepEqual(r, { orderId: 'o1', status: 'reserved', items });
  }
  assert.equal(await svc.available('widget'), 7);

  await svc.release('o1');
  assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 10, reserved: 0, sold: 0 });
});

// --- bundles held partially -----------------------------------------------

test('a bundle with an out-of-stock item holds none of its items', async () => {
  const svc = await service({ shirt: 10, hat: 1 });

  await assert.rejects(
    svc.reserve('o1', [{ sku: 'shirt', qty: 2 }, { sku: 'hat', qty: 2 }]),
    err => err instanceof InsufficientStockError && err.sku === 'hat' && err.available === 1
  );

  assert.equal(await svc.available('shirt'), 10);
  assert.equal(await svc.available('hat'), 1);
  // The rejected order left nothing behind, so the id can be used again.
  await svc.reserve('o1', [{ sku: 'shirt', qty: 2 }, { sku: 'hat', qty: 1 }]);
  assert.equal(await svc.available('shirt'), 8);
});

test('a bundle with an unknown item holds none of its items', async () => {
  const svc = await service({ shirt: 10 });

  await assert.rejects(svc.reserve('o1', [{ sku: 'shirt', qty: 2 }, { sku: 'nope', qty: 1 }]), UnknownSkuError);

  assert.equal(await svc.available('shirt'), 10);
});

test('concurrent bundles competing for the last units are all-or-nothing', async () => {
  const svc = await service({ shirt: 20, hat: 5 });

  const { fulfilled, rejected } = await settle(
    Array.from({ length: 12 }, (_, i) => {
      // Alternate item order so bundles lock the same SKUs in different orders.
      const items = i % 2 === 0
        ? [{ sku: 'shirt', qty: 1 }, { sku: 'hat', qty: 1 }]
        : [{ sku: 'hat', qty: 1 }, { sku: 'shirt', qty: 1 }];
      return svc.reserve(`o${i}`, items);
    })
  );

  assert.equal(fulfilled.length, 5);
  assert.equal(rejected.length, 7);
  assert.deepEqual(await svc.snapshot('shirt'), { sku: 'shirt', stock: 20, reserved: 5, sold: 0 });
  assert.deepEqual(await svc.snapshot('hat'), { sku: 'hat', stock: 5, reserved: 5, sold: 0 });
});

// --- sold counted twice ---------------------------------------------------

test('a retried commit sells the units once', async () => {
  const svc = await service({ widget: 10 });
  await svc.reserve('o1', [{ sku: 'widget', qty: 3 }]);

  const results = await Promise.all(Array.from({ length: 4 }, () => svc.commit('o1')));

  for (const r of results) {
    assert.equal(r.status, 'committed');
  }
  assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 7, reserved: 0, sold: 3 });
});

// --- no service-wide lock (INC-5490) --------------------------------------

test('calls on other skus and orders do not wait for a stalled call', async () => {
  const store = new GatedStore();
  const svc = await service({ slow: 10, fast: 10 }, { store });
  await svc.reserve('fast-committed', [{ sku: 'fast', qty: 1 }]);
  await svc.reserve('fast-released', [{ sku: 'fast', qty: 1 }]);

  const resume = store.pause('sku:slow');
  const stalled = svc.reserve('slow-order', [{ sku: 'slow', qty: 1 }]);

  await within(1000, svc.reserve('fast-order', [{ sku: 'fast', qty: 1 }]));
  await within(1000, svc.commit('fast-committed'));
  await within(1000, svc.release('fast-released'));
  await within(1000, svc.addStock('fast', 1));
  await within(1000, svc.snapshot('fast'));
  assert.deepEqual(await svc.snapshot('fast'), { sku: 'fast', stock: 10, reserved: 1, sold: 1 });

  resume();
  assert.equal((await stalled).status, 'reserved');
  assert.equal(await svc.available('slow'), 9);
});

test('calls do not wait for a stalled expire on another order', async () => {
  let t = 0;
  const store = new GatedStore();
  const svc = await service({ slow: 10, fast: 10 }, { store, now: () => t, reservationTtlMs: 1000 });
  await svc.reserve('slow-order', [{ sku: 'slow', qty: 1 }]);
  t = 5000;

  const resume = store.pause('sku:slow');
  const expiring = svc.expire();

  await within(1000, svc.reserve('fast-order', [{ sku: 'fast', qty: 1 }]));
  await within(1000, svc.commit('fast-order'));

  resume();
  assert.deepEqual(await expiring, ['slow-order']);
});

test('services sharing a store coordinate with each other', async () => {
  const store = new Store();
  const a = new InventoryService({ store });
  const b = new InventoryService({ store });
  await a.addStock('widget', 10);

  const { fulfilled } = await settle(
    Array.from({ length: 20 }, (_, i) => (i % 2 ? a : b).reserve(`o${i}`, [{ sku: 'widget', qty: 1 }]))
  );

  assert.equal(fulfilled.length, 10);
  assert.deepEqual(await a.snapshot('widget'), { sku: 'widget', stock: 10, reserved: 10, sold: 0 });
});

// --- mixed load ------------------------------------------------------------

test('counters match the orders under a mixed concurrent load', async () => {
  const random = prng(5521);
  let t = 0;
  const skus = ['a', 'b', 'c', 'd'];
  const svc = new InventoryService({ store: new JitterStore(random), now: () => t, reservationTtlMs: 1000 });
  const added = {};
  for (const sku of skus) {
    await svc.addStock(sku, 20);
    added[sku] = 20;
  }

  const pick = list => list[Math.floor(random() * list.length)];
  const calls = [];
  for (let i = 0; i < 400; i++) {
    const orderId = `o${Math.floor(random() * 120)}`;
    const roll = random();
    if (roll < 0.45) {
      const count = 1 + Math.floor(random() * 3);
      const items = [...skus].sort(() => random() - 0.5).slice(0, count)
        .map(sku => ({ sku, qty: 1 + Math.floor(random() * 3) }));
      calls.push(svc.reserve(orderId, items));
    } else if (roll < 0.7) {
      calls.push(svc.commit(orderId));
    } else if (roll < 0.9) {
      calls.push(svc.release(orderId));
    } else if (roll < 0.95) {
      const sku = pick(skus);
      const qty = 1 + Math.floor(random() * 3);
      added[sku] += qty;
      calls.push(svc.addStock(sku, qty));
    } else {
      t += 400;
      calls.push(svc.expire());
    }
  }
  await Promise.allSettled(calls);

  const expected = Object.fromEntries(skus.map(sku => [sku, { reserved: 0, sold: 0 }]));
  for (const key of await svc.store.keys('order:')) {
    const order = await svc.store.get(key);
    for (const { sku, qty } of order.items) {
      if (order.status === 'reserved') expected[sku].reserved += qty;
      if (order.status === 'committed') expected[sku].sold += qty;
    }
  }
  for (const sku of skus) {
    const snap = await svc.snapshot(sku);
    assert.equal(snap.reserved, expected[sku].reserved, `reserved for ${sku}`);
    assert.equal(snap.sold, expected[sku].sold, `sold for ${sku}`);
    assert.equal(snap.stock, added[sku] - expected[sku].sold, `stock for ${sku}`);
    assert.ok(snap.stock - snap.reserved >= 0, `available for ${sku}`);
  }
});

