test('commit racing release settles on exactly one outcome', async () => {
  for (const first of ['commit', 'release']) {
    const svc = await service({ widget: 10 });
    await svc.reserve('o1', [{ sku: 'widget', qty: 4 }]);

    const calls = first === 'commit'
      ? [svc.commit('o1'), svc.release('o1')]
      : [svc.release('o1'), svc.commit('o1')];
    const { fulfilled, rejected } = await settle(calls);

