test('calls on other skus and orders do not wait for a stalled call', async () => {
  const store = new GatedStore();
  const svc = await service({ slow: 10, fast: 10 }, { store });
  await svc.reserve('fast-committed', [{ sku: 'fast', qty: 1 }]);
  await svc.reserve('fast-released', [{ sku: 'fast', qty: 1 }]);

  const resume = store.pause('sku:slow');
  const stalled = svc.reserve('slow-order', [{ sku: 'slow', qty: 1 }]);

  await within(1000, svc.reserve('fast-order', [{ sku: 'fast', qty: 1 }]));
  await within(1000, svc.commit('fast-committed'));
  await within(1000, svc.release('fast-released'));
  await within(1000, svc.addStock('fast', 1));
  await within(1000, svc.snapshot('fast'));
  assert.deepEqual(await svc.snapshot('fast'), { sku: 'fast', stock: 10, reserved: 1, sold: 1 });

  resume();
  assert.equal((await stalled).status, 'reserved');
  assert.equal(await svc.available('slow'), 9);
});

test('calls do not wait for a stalled expire on another order', async () => {
  let t = 0;
  const store = new GatedStore();
  const svc = await service({ slow: 10, fast: 10 }, { store, now: () => t, reservationTtlMs: 1000 });
  await svc.reserve('slow-order', [{ sku: 'slow', qty: 1 }]);
  t = 5000;

  const resume = store.pause('sku:slow');
  const expiring = svc.expire();

  await within(1000, svc.reserve('fast-order', [{ sku: 'fast', qty: 1 }]));
  await within(1000, svc.commit('fast-order'));

  resume();
  assert.deepEqual(await expiring, ['slow-order']);
});

test('services sharing a store coordinate with each other', async () => {
  const store = new Store();
  const a = new InventoryService({ store });
  const b = new InventoryService({ store });
  await a.addStock('widget', 10);

  const { fulfilled } = await settle(
    Array.from({ length: 20 }, (_, i) => (i % 2 ? a : b).reserve(`o${i}`, [{ sku: 'widget', qty: 1 }]))
  );

  assert.equal(fulfilled.length, 10);
  assert.deepEqual(await a.snapshot('widget'), { sku: 'widget', stock: 10, reserved: 10, sold: 0 });
});

// --- mixed load ------------------------------------------------------------

test('counters match the orders under a mixed concurrent load', async () => {
  const random = prng(5521);
  let t = 0;
  const skus = ['a', 'b', 'c', 'd'];
  const svc = new InventoryService({ store: new JitterStore(random), now: () => t, reservationTtlMs: 1000 });
  const added = {};
  for (const sku of skus) {
    await svc.addStock(sku, 20);
    added[sku] = 20;
  }

  const pick = list => list[Math.floor(random() * list.length)];
  const calls = [];
  for (let i = 0; i < 400; i++) {
    const orderId = `o${Math.floor(random() * 120)}`;
    const roll = random();
    if (roll < 0.45) {
      const count = 1 + Math.floor(random() * 3);
      const items = [...skus].sort(() => random() - 0.5).slice(0, count)
        .map(sku => ({ sku, qty: 1 + Math.floor(random() * 3) }));
      calls.push(svc.reserve(orderId, items));
    } else if (roll < 0.7) {
      calls.push(svc.commit(orderId));
    } else if (roll < 0.9) {
      calls.push(svc.release(orderId));
    } else if (roll < 0.95) {
      const sku = pick(skus);
      const qty = 1 + Math.floor(random() * 3);
      added[sku] += qty;
      calls.push(svc.addStock(sku, qty));
    } else {
      t += 400;
      calls.push(svc.expire());
    }
  }
  await Promise.allSettled(calls);

  const expected = Object.fromEntries(skus.map(sku => [sku, { reserved: 0, sold: 0 }]));
  for (const key of await svc.store.keys('order:')) {
    const order = await svc.store.get(key);
    for (const { sku, qty } of order.items) {
      if (order.status === 'reserved') expected[sku].reserved += qty;
      if (order.status === 'committed') expected[sku].sold += qty;
    }
  }
  for (const sku of skus) {
    const snap = await svc.snapshot(sku);
    assert.equal(snap.reserved, expected[sku].reserved, `reserved for ${sku}`);
    assert.equal(snap.sold, expected[sku].sold, `sold for ${sku}`);
    assert.equal(snap.stock, added[sku] - expected[sku].sold, `stock for ${sku}`);
    assert.ok(snap.stock - snap.reserved >= 0, `available for ${sku}`);
  }
});

