'use strict';

// Per-key async mutex. Callers that lock the same key run one at a time, in
// arrival order; callers whose keys do not overlap never wait for each other.
class KeyedLock {
  constructor() {
    // key -> promise that settles when the last caller queued on it is done
    this.tails = new Map();
  }

  /**
   * Run fn while holding every key in `keys`. Keys are taken in sorted order,
   * so callers locking overlapping sets cannot deadlock each other.
   */
  async run(keys, fn) {
    const releases = [];
    try {
      for (const key of [...new Set(keys)].sort()) {
        releases.push(await this.acquire(key));
      }
      return await fn();
    } finally {
      for (const release of releases.reverse()) {
        release();
      }
    }
  }

  acquire(key) {
    const previous = this.tails.get(key) || Promise.resolve();
    let release;
    const done = new Promise(resolve => { release = resolve; });
    this.tails.set(key, done);
    return previous.then(() => () => {
      if (this.tails.get(key) === done) {
        this.tails.delete(key);
      }
      release();
    });
  }
}

module.exports = { KeyedLock };

